        ks2 += ik2;
        ks3 += ik2 * ik;
        ks4 += ik2 * ik2;
        dm *= dl;
        const double b = w / (md + 1.0) * dm;
        const double m10 = ks1, m20 = ks2, m30 = 2.0 * ks3, m40 = 6.0 * ks4, m01 = -(md + 1.0);
        const double bz0 = m10*m10;
        const double bz1 = bz0 + m20;
        const double bz2 = m01*m01;
