        T10 += b * (m10);
        T01 += b * (m01);
        T20 += b * (bz1);
        T11 += b * (m01*m10);
        T02 += b * (bz2);
        T30 += b * (bz3);
        T21 += b * (bz1*m01);
        T12 += b * (bz2*m10);
        T03 += b * (bz4);
        T40 += b * (6.0*bz0*m20 + m10*m10*m10*m10 + 4.0*m10*m30 + 3.0*(m20*m20) + m40);
